/* Workflow extensions: document rotation, transaction history, batch masks,
   final-PDF preview cache, project backup, and resizable document navigation. */
const editFields=['masks','notes','rotation','width','height'];
function editState(c=current()){return c.files.map(f=>({id:f.id,...Object.fromEntries(editFields.map(k=>[k,structuredClone(f[k]??(k==='rotation'?0:[]))]))}));}
function historyState(){return current().editHistory??={past:[],future:[]};}
snapshot=function(){const h=historyState();h.past.push(editState());if(h.past.length>25)h.past.shift();h.future=[];dirty();};
function invalidatePage(f){f.accepted=false;f.status=f.status==='處理失敗'?f.status:'待確認';f.revision=(f.revision||0)+1;delete f.approvedRevision;f.checks=[false,false,false];}
function travelEdits(forward){const h=historyState(),from=forward?h.future:h.past,to=forward?h.past:h.future;if(!from.length)return;to.push(editState());const states=from.pop();for(const s of states){const f=current().files.find(p=>p.id===s.id);if(f&&JSON.stringify(Object.fromEntries(editFields.map(k=>[k,f[k]])))!==JSON.stringify(Object.fromEntries(editFields.map(k=>[k,s[k]])))){Object.assign(f,s);invalidatePage(f);}}selection=null;pdfWorkReady='';markCaseUnsaved();render();notify(forward?'已重做；受影響頁面請重新確認':'已復原；受影響頁面請重新確認');}
undoEdit=()=>travelEdits(false);
function rotateRect(o){return {...o,x:100-o.y-o.h,y:o.x,w:o.h,h:o.w};}
function rotateDrawing(clockwise=true){const f=file();if(!f?.sourceId)return notify('請匯入 PDF 後使用旋轉');snapshot();for(let i=0;i<(clockwise?1:3);i++){f.masks=f.masks.map(rotateRect);f.notes=f.notes.map(n=>({...rotateRect(n),textRotation:((n.textRotation||0)+90)%360}));[f.width,f.height]=[f.height,f.width];f.rotation=((f.rotation||0)+90)%360;}selection=null;pdfDrawMode=false;pdfWorkReady='';zoomLevel=100;render();notify('圖面、遮蔽及備註已一起旋轉，請重新確認');}
const unrotatedFit=fitNote;fitNote=function(el){const n=file()?.notes[+el.dataset.index];if(!n?.textRotation)return unrotatedFit(el);const p=$('#paper'),scale=p.clientWidth/file().width,c=el.querySelector('.object-content'),angle=n.textRotation,odd=angle%180!==0,pad=4*scale;el.style.padding='0';el.style.fontSize=(n.fontSize||10)*scale+'px';const w=el.clientWidth,h=el.clientHeight;Object.assign(c.style,{position:'absolute',left:'50%',top:'50%',width:(odd?h:w)+'px',height:(odd?w:h)+'px',padding:pad+'px',boxSizing:'border-box',transform:`translate(-50%,-50%) rotate(${angle}deg)`,transformOrigin:'center',overflow:'auto'});};
const ruleReset=clearObjects;clearObjects=function(type,reset=false){if(type!=='mask'||!reset||!file()?.sourceId)return ruleReset(type,reset);if(!confirm('恢復目前方向的規則候選區？'))return;snapshot();let masks=pdfRuleMasks(file().rule||'manual');for(let r=0;r<(file().rotation||0);r+=90)masks=masks.map(rotateRect);file().masks=masks;selection=null;render();};
function toolIcon(path){return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`;}
function openBatchMasks(){const f=file();if(!f?.sourceId||!f.masks.length)return notify('請先圈選遮蔽區');const targets=current().files.filter(p=>p.sourceId===f.sourceId&&p!==f);caseDialog('batchMaskDialog',`<h2>批次套用遮蔽</h2><p>來源：${esc(pdfLabel(f))}。保留既有遮蔽，套用後需逐頁確認，可整批復原。</p><h3>套用物件</h3>${f.masks.map((m,i)=>`<label class="checkrow"><input type="checkbox" name="batchMask" value="${i}" checked><span>遮蔽 ${i+1}</span></label>`).join('')}<h3>目標頁面</h3><p>僅預選尺寸與旋轉方向相同的頁面；不同版型仍須人工核對。</p><div class="batch-targets">${targets.map(p=>{const same=Math.abs(p.width-f.width)<1&&Math.abs(p.height-f.height)<1&&(p.rotation||0)===(f.rotation||0);return `<label class="checkrow"><input type="checkbox" name="batchPage" value="${esc(p.id)}" ${same&&p.status!=='處理失敗'?'checked':''} ${p.status==='處理失敗'?'disabled':''}><span>第 ${p.pageIndex+1} 頁 ${same?'':'· 尺寸或方向不同'}</span></label>`;}).join('')||'<p>此檔案沒有其他頁面。</p>'}</div><div class="actions"><button onclick="this.closest('dialog').close()">取消</button><button class="primary" onclick="applyBatchMasks()">套用至所選頁面</button></div>`);}
function applyBatchMasks(){const dialog=$('#batchMaskDialog'),src=file(),areas=[...dialog.querySelectorAll('[name=batchMask]:checked')].map(e=>structuredClone(src.masks[+e.value])),ids=new Set([...dialog.querySelectorAll('[name=batchPage]:checked')].map(e=>e.value));if(!areas.length||!ids.size)return notify('請選擇遮蔽物件與目標頁面');const targets=current().files.filter(p=>ids.has(p.id)&&p.sourceId===src.sourceId&&p!==src&&p.status!=='處理失敗');const changes=targets.map(p=>({p,add:areas.filter(a=>!p.masks.some(m=>['x','y','w','h'].every(k=>Math.abs(m[k]-a[k])<.01)&&m.color===a.color))})).filter(x=>x.add.length);if(!changes.length)return notify('所選頁面已有相同遮蔽，未重複加入');const h=historyState();h.past.push(editState());if(h.past.length>25)h.past.shift();h.future=[];for(const {p,add}of changes){p.masks.push(...structuredClone(add));invalidatePage(p);}markCaseUnsaved();dialog.close();render();notify(`已套用至 ${changes.length} 頁，請逐頁確認`);}
const documentToolPage=workPage;workPage=function(){let html=documentToolPage();if(!current()?.files.length)return html;const h=historyState();html=html.replace(/<button[^>]*onclick="undoEdit\(\)"[^>]*>[\s\S]*?<\/button>/,`<button ${h.past.length?'':'disabled'} onclick="undoEdit()" title="復原最近一次操作">${uiIcon('undo')}復原</button><button ${h.future.length?'':'disabled'} onclick="travelEdits(true)">${toolIcon('<path d="M20 7H10a6 6 0 0 0 0 12M16 3l4 4-4 4"/>')}重做</button>`);if(file().sourceId){html=html.replace('<div class="canvasbar">',`<div class="canvasbar"><button title="逆時針旋轉 90°，物件一起旋轉" aria-label="逆時針旋轉 90 度" onclick="rotateDrawing(false)">${toolIcon('<path d="M3 10a9 9 0 1 1 2 9M3 4v6h6"/>')}</button><button title="順時針旋轉 90°，物件一起旋轉" aria-label="順時針旋轉 90 度" onclick="rotateDrawing(true)">${toolIcon('<path d="M21 10a9 9 0 1 0-2 9M21 4v6h-6"/>')}</button><button ${file().masks.length&&file().pageCount>1?'':'disabled'} onclick="openBatchMasks()">${uiIcon('mask')}批次套用</button>`);}return html.replace('<div class="filelist">','<div class="filelist resizable-filelist"><div class="filelist-resizer" role="separator" tabindex="0" aria-label="調整圖面清單寬度" aria-orientation="vertical"></div>');};
let fileListSizeObserver;
function bindListResize(){
 fileListSizeObserver?.disconnect();const bar=document.querySelector('.filelist-resizer'),ws=document.querySelector('.workspace');if(!bar||!ws)return;
 const collapsed=()=>document.body.classList.contains('sidebar-collapsed');
 const key=()=>collapsed()?'drawing-list-width-collapsed':'drawing-list-width';
 const read=k=>{try{return Number(localStorage.getItem(k))||0}catch{return 0}};
 const limits=()=>({min:180,max:Math.max(180,Math.min(460,ws.clientWidth-240-28-300))});
 const preferred=()=>read(key())||(Math.max(220,read('drawing-list-width'))+(collapsed()?180:0));
 const set=(value,persist=false)=>{if(!window.matchMedia('(min-width:1101px)').matches){ws.style.removeProperty('--file-width');return;}const {min,max}=limits(),w=Math.max(min,Math.min(max,value));ws.style.setProperty('--file-width',w+'px');bar.setAttribute('aria-valuemin',min);bar.setAttribute('aria-valuemax',Math.round(max));bar.setAttribute('aria-valuenow',Math.round(w));if(persist)try{localStorage.setItem(key(),w)}catch{}sizeDrawing();};
 set(preferred());fileListSizeObserver=new ResizeObserver(()=>set(preferred()));fileListSizeObserver.observe(ws);
 bar.onpointerdown=e=>{e.preventDefault();const x=e.clientX,w=bar.parentElement.clientWidth;bar.setPointerCapture(e.pointerId);bar.onpointermove=ev=>set(w+ev.clientX-x,true);bar.onpointerup=bar.onpointercancel=()=>bar.onpointermove=null;};
 bar.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();set(bar.parentElement.clientWidth+(e.key==='ArrowRight'?10:-10),true);}};
}
// Cache only the most recently generated document, by complete page content.
let finalCache=null,finalPending=null;
function finalKey(g){return g.id+JSON.stringify(g.pages.map(pdfPageData));}
async function finalDocument(g,signal){const key=finalKey(g);if(finalCache?.key===key)return finalCache.bytes;if(finalPending?.key===key)return finalPending.promise;const promise=(async()=>{const pages=g.pages.map(pdfPageData),bytes=await pdfBytes(g.pages[0]),result=await pdfCall('export',{bytes,pages},signal);if(finalKey(g)!==key)throw Error('圖面已修改，請重新產生預覽');finalCache={key,bytes:result};return result;})();finalPending={key,promise};try{return await promise;}finally{if(finalPending?.promise===promise)finalPending=null;}}
const workMount=pdfMountPreview;pdfMountPreview=async function(){if(route!=='review')return workMount();const f=file(),canvas=document.querySelector('.pdf-canvas');if(!f?.sourceId||!canvas)return;const token=++pdfPreviewToken,key=pdfKey(f),message=canvas.parentElement.querySelector('.pdf-render-message');try{const g=pdfGroups().find(g=>g.id===f.sourceId),bytes=await finalDocument(g);if(token!==pdfPreviewToken)return;const result=await pdfCall('render',{bytes,pageIndex:f.pageIndex,width:Math.max(1400,canvas.parentElement.clientWidth*devicePixelRatio)});if(token!==pdfPreviewToken||!canvas.isConnected)return;const bitmap=await createImageBitmap(new Blob([result.png],{type:'image/png'}));canvas.width=bitmap.width;canvas.height=bitmap.height;canvas.getContext('2d').drawImage(bitmap,0,0);bitmap.close();message?.remove();pdfPreviewReady=key;}catch(e){if(token===pdfPreviewToken&&message){message.textContent=e.message;message.classList.add('pdf-render-error');}}};
let continuousToken=0,continuousObserver;
function closeContinuous(){continuousToken++;continuousObserver?.disconnect();$('#continuousDialog')?.close();$('#continuousDialog')?.remove();}
async function openContinuous(){const f=file(),g=pdfGroups().find(g=>g.id===f?.sourceId);if(!g)return;closeContinuous();const token=continuousToken;caseDialog('continuousDialog',`<div class="cardhead"><h2>整份出圖預覽 · ${esc(g.name)}</h2><button onclick="closeContinuous()">關閉</button></div><p id="continuousStatus" role="status">正在產生交付 PDF…</p><div id="continuousSheets"></div>`);const d=$('#continuousDialog');d.addEventListener('cancel',closeContinuous);try{const bytes=await finalDocument(g);if(token!==continuousToken)return;$('#continuousStatus').textContent=`共 ${g.pages.length} 頁 · ${g.pages.every(isExportReady)?'全部已確認':'尚有未確認頁面，不能匯出'}`;const sheets=$('#continuousSheets');sheets.innerHTML=g.pages.map(p=>`<figure data-page="${p.pageIndex}"><figcaption>第 ${p.pageIndex+1} 頁</figcaption><div style="aspect-ratio:${p.width}/${p.height}"></div></figure>`).join('');let queue=Promise.resolve();continuousObserver=new IntersectionObserver(entries=>{for(const e of entries){e.target.dataset.visible=e.isIntersecting?'1':'0';if(!e.isIntersecting){e.target.querySelector('img')?.remove();continue;}queue=queue.then(async()=>{const el=e.target;if(token!==continuousToken||el.dataset.visible!=='1'||el.querySelector('img'))return;const result=await pdfCall('render',{bytes,pageIndex:+el.dataset.page,width:1400});if(token!==continuousToken||el.dataset.visible!=='1')return;const img=new Image(),url=URL.createObjectURL(new Blob([result.png],{type:'image/png'}));img.onload=img.onerror=()=>URL.revokeObjectURL(url);img.alt=`第 ${+el.dataset.page+1} 頁出圖`;img.src=url;el.querySelector('div').append(img);}).catch(e=>{if(token===continuousToken)$('#continuousStatus').textContent=e.message;});}},{root:sheets,rootMargin:'200px'});sheets.querySelectorAll('figure').forEach(el=>continuousObserver.observe(el));}catch(e){if(token===continuousToken)$('#continuousStatus').textContent=e.message;}}
const documentReview=reviewPage;reviewPage=function(){return documentReview().replace('<h2>最終出圖預覽</h2>','<h2>最終出圖預覽</h2>'+(file()?.sourceId&&pdfGroups().some(g=>g.id===file().sourceId&&g.pages.length>1)?'<button onclick="openContinuous()">整份連續預覽</button>':''));};
const toolsRender=render;render=function(){toolsRender();if(route==='work')bindListResize();};
render();
